  "is_atomic": true,
  "atomic_questions": [
    "Is the 12-hour limit a shared deadline (all furnaces must finish by hour 12, so each furnace's total processing time must be at most 12 hours), or is it a total budget of furnace-hours (the sum of processing time across both furnaces must be at most 12 hours)?"
  ],
  "rationale": "The response asks for a single policy choice between two mutually exclusive interpretations of the 12-hour limit."
}

